WITH exploded AS (SELECT id, effective_from, currency, EXPLODE(discounts) AS tier_value FROM price_tiers) SELECT id, effective_from, currency, tier_value, RANK() OVER (PARTITION BY currency ORDER BY tier_value NULLS FIRST) AS tier_value_rank, SUM(tier_value) OVER (PARTITION BY currency) AS currency_sum_tier_value, PERCENT_RANK() OVER (ORDER BY tier_value DESC NULLS FIRST) AS tier_value_percent_rank FROM exploded;
